      var depth = 12 + Math.random() * 8;
      var geom = new THREE.BoxGeometry(width, height, depth);
      var mat = new THREE.MeshStandardMaterial({ color: 0x332211 });
      var mesh = new THREE.Mesh(geom, mat);
