    var containerGeometry = new THREE.SphereGeometry(1.8, 16, 16);
    var containerMaterial = new THREE.MeshStandardMaterial({ color: 0xFFFF00 });
    var container = new THREE.Mesh(containerGeometry, containerMaterial);
