    sceneObjects.push(leftWall);

    var rightWall = new THREE.Mesh(wallGeometry, stoneMaterial);
    rightWall.position.set(20, 10, 0);
    scene.add(rightWall);
    sceneObjects.push(rightWall);

    // 3. Skull wall niche with bone arrangement (ossuary)
