		var sensorGeo = new THREE.SphereGeometry(0.4, 8, 8);
		var sensorMat = createMaterial(0xffd700);
		var sensor = new THREE.Mesh(sensorGeo, sensorMat);
		sensor.position.set(0, 10, 0);
