		pipe1.rotation.z = Math.PI / 2;
		pipe1.position.set(10, 2, 0);
		pipeGroup.add(pipe1);

		var pipe2Geo = new THREE.CylinderGeometry(0.4, 0.4, 15, 8);
		var pipe2 = new THREE.Mesh(pipe2Geo, pipeMat);
		pipe2.rotation.x = Math.PI / 2;
		pipe2.position.set(0, 5, -8);
