		var boatGeo = new THREE.CylinderGeometry(1.5, 1.8, 8, 12);
		var boatMat = createMaterial(0xff6347);
		var boat = addAndTrack(new THREE.Mesh(boatGeo, boatMat));
		boat.position.set(-35, 20, -32);
