  var lightbeamCone;
  var fireSphere;
  var ritualCircle;
  var boatMesh;
  var bellSphere;
  var currentFogDensity = 0.03;
  var ritualPulseTime = 0;
  var boatBobTime = 0;
  var bellRingTime = 0;
  var lastHKeyTime = 0;
  var lastLKeyTime = 0;
  var hPressed = false;
  var lPressed = false;
