    allObjects.push(pavilionGrp);

    // Library tower
    var libraryGrp = createLibraryTower();
    scene.add(libraryGrp);
    allObjects.push(libraryGrp);

    // Face tower
    var faceGrp = createFaceTower();
    scene.add(faceGrp);
    allObjects.push(faceGrp);

    // Create enemies
