  var conduit1Geo = new THREE.BoxGeometry(2, 15, 2);
  var conduitMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
  var conduit1 = new THREE.Mesh(conduit1Geo, conduitMat);
  conduit1.position.set(-60, 12, -70);
  scene.add(conduit1);
