    var geometry = new THREE.BoxGeometry(100, 50, 1);
    var material = new THREE.MeshBasicMaterial({ map: texture });
    var plane = new THREE.Mesh(geometry, material);
    plane.position.set(0, 100, -200);
    plane.position.z -= 0.1;
    scene.add(plane);
    objects.push(plane);

    updateHUDText();
