    var boothGeom = new THREE.BoxGeometry(15, 15, 15);
    var boothMat = new THREE.MeshLambertMaterial({ color: 0xaa0000 });
    var booth = new THREE.Mesh(boothGeom, boothMat);
    booth.position.set(-250, 7, 0);
    booth.castShadow = true;
    scene.add(booth);
