    frontWall.position.set(0, 2, 20);
    frontWall.castShadow = true;
    scene.add(frontWall);

    // Back wall
    var backWall = new THREE.Mesh(wallGeometry, wallMaterial);
    backWall.position.set(0, 2, -20);
    backWall.castShadow = true;
