    var gateGeometry = new THREE.BoxGeometry(5, 3, 0.5);
    var gateMaterial = new THREE.MeshStandardMaterial({ color: 0x5a3a1a });
    var gate = new THREE.Mesh(gateGeometry, gateMaterial);
