      { x: 200, z: 100, type: 'straight' },
      { x: 200, z: 0, type: 'straight' },
      { x: 200, z: -100, type: 'straight' },
      { x: 200, z: -200, type: 'corner' },
      { x: 100, z: -200, type: 'straight' },
      { x: 0, z: -200, type: 'gap' }
